#include <iostream>
#include <string>
#include <vector>
using namespace std;
typedef unsigned long long ull;
const ull BASE = 131, MOD = (1ULL<<61)-1;
ull mod(ull a){ return a % MOD; }
ull mulmod(ull a, ull b){
    __uint128_t r = (__uint128_t)a * b;
    return mod((ull)(r >> 61) + (ull)(r & MOD));
}
int main(){
    string T, P; cin >> T >> P;
    int n=T.size(), m=P.size();
    if(m>n){ cout << -1; return 0; }
    // compute pattern hash and initial window hash
    ull ph=0, th=0, pw=1;
    for(int i=0;i<m;i++){
        ph = mod(mulmod(ph,BASE) + P[i]);
        th = mod(mulmod(th,BASE) + T[i]);
        if(i>0) pw = mulmod(pw, BASE);
    }
    bool found=false;
    for(int i=0;i<=n-m;i++){
        if(th==ph && T.substr(i,m)==P){ cout << i << "\n"; found=true; }
        if(i<n-m){
            th = mod(mulmod(th,BASE) + T[i+m] - mulmod(pw, T[i]) + 2*MOD);
        }
    }
    if(!found) cout << -1;
    return 0;
}

