import java.util.*;
public class Main {
    static final long BASE=131, MOD=(1L<<31)-1;
    public static void main(String[] args){
        Scanner sc=new Scanner(System.in);
        String T=sc.next(), P=sc.next();
        int n=T.length(), m=P.length();
        if(m>n){System.out.println(-1);return;}
        long ph=0,th=0,pw=1;
        for(int i=0;i<m;i++){
            ph=(ph*BASE+P.charAt(i))%MOD;
            th=(th*BASE+T.charAt(i))%MOD;
            if(i>0) pw=pw*BASE%MOD;
        }
        List<Integer> res=new ArrayList<>();
        for(int i=0;i<=n-m;i++){
            if(th==ph && T.substring(i,i+m).equals(P)) res.add(i);
            if(i<n-m) th=((th-pw*T.charAt(i)%MOD+MOD)*BASE+T.charAt(i+m))%MOD;
        }
        if(res.isEmpty()) System.out.println(-1);
        else for(int x:res) System.out.println(x);
    }
}
